import"./chunk-2NFLSA4Y.js";var a={newtonsCradle:{theory:{concept:"[[Newton's cradle is a row of identical balls hanging side by side; it shows how momentum and kinetic energy pass from body to body in elastic collisions.]] The balls in the middle pass the motion on while hardly moving themselves."},section:{transfer:{title:"Motion travels through the row",text:"Five identical balls touch when hanging at rest. The released group falls under gravity. At the bottom, the incoming balls stop and the same number at the opposite end move away. The middle balls transmit the interaction and remain almost still in an ideal cradle."},both:{title:"Momentum and energy together",text:"At a perfectly elastic collision, both momentum and kinetic energy are conserved. For identical balls in the ideal transfer pattern, the outgoing group has the same number and speed as the incoming group. Momentum alone would not determine this result; the ideal contact behaviour matters too."},thirdLaw:{title:"Action and reaction at every contact",text:"When neighbouring balls touch, each exerts an equal and opposite force on the other. These forces act on different balls. In this ideal model contact is instantaneous, so we compare momenta before and after the collision instead of inventing a finite peak force. Compare this with the cannon\u2019s recoil in the related topic."},swing:{title:"Why the balls come back",text:"After the collision the outgoing balls rise, converting kinetic energy into gravitational potential energy. Without losses, they return to the release height and swing back. A longer string slows the swing. The small-angle period is approximately 2\u03C0\u221A(L/g); large swings take longer."},losses:{title:"Why a real cradle slows down",text:"Air resistance, sound, deformation and friction remove mechanical energy in a real cradle. Here the damping control adds resistance during the swings. Collisions remain perfectly elastic, so this control does not pretend to reproduce sound or contact losses."},check:{title:"Predict, then try",text:"Release two balls. How many should emerge? Increase the release angle: do the balls rise higher? Increase all ball masses together: does the timing change? In this ideal model mass changes energy and momentum, but not the swing timing."}},param:{released:"Balls to release",amplitude:"Release angle",length:"Effective pendulum length",gravity:"Gravity",mass:"Mass of each ball",damping:"Swing damping",timeStep:"Simulation timestep"},hint:{released:"Choose one or two adjacent balls at the left end. All five balls have the same mass.",amplitude:"The released balls start at rest at this angle from the vertical.",length:"Distance from the midpoint between the two anchors to the ball centre. Longer suspension gives a slower swing.",gravity:"Gravity controls how fast the balls swing.",mass:"All five balls change mass together. The ideal swing timing stays the same.",damping:"0 gives lossless swings. A larger coefficient removes energy between collisions.",timeStep:"Fixed physics step. Collision times are located within each step."},preset:{one:"One ball",two:"Two balls",small:"Small swing",medium:"Medium swing",large:"Large swing"},measure:{outgoingCount:"Balls emerging at last impact",impacts:"Transfers so far",angleLeft:"Left-end angle",angleRight:"Right-end angle",energy:"Total mechanical energy",retained:"Initial energy remaining",periodSmall:"Small-angle period estimate",incomingMomentum:"Momentum just before last impact",outgoingMomentum:"Momentum just after last impact",impactError:"Momentum difference at last impact"},graph:{angle:"End balls take turns swinging",energy:"Mechanical energy through successive transfers"},view:{transfer:"Released: {incoming} \xB7 emerging: {outgoing}",impact:"Elastic transfer \xB7 momentum and energy conserved",ideal:"Ideal cradle \xB7 equal balls \xB7 elastic collisions",vectorsOption:"Velocity of the swinging group",guidesOption:"Vertical reference lines"},formula:{count:"Ideal equal-ball transfer",momentum:"Momentum before and after impact",energy:"Kinetic energy before and after impact",speed:"Bottom speed without damping",period:"Period estimate for small swings",motion:"Full swing equation with damping"},assumption:{identical:"Five identical balls hang on equal massless strings. Motion is planar, without spin, and the supports are rigid.",transfer:"At the bottom, an instantaneous perfectly elastic transfer sends the same number of balls to the opposite side. Contact deformation and waves inside the balls are not simulated; this is an ideal transfer model.",losses:"The damping control acts during swings only. Collisions do not lose energy to sound or deformation.",supports:"The supports exert external forces during each swing. Horizontal momentum is conserved across a bottom collision, not throughout a whole oscillation.",drawing:"The apparatus is a 3D schematic with spherical balls and paired strings. The swing remains planar. L is the effective distance from the midpoint between the two anchors to the ball centre; each diagonal string is slightly longer. Ball radius is 12% of L."},challenge:{one:{title:"One in, one out",description:"Make one ball emerge at the other end and observe at least four transfers.",hint:"Release one ball and let the cradle run."},two:{title:"Two in, two out",description:"Make two balls emerge together and observe at least four transfers.",hint:"Select two balls to release, then run the experiment."},high:{title:"Return high",description:"Make the right-hand balls rise to at least 44\xB0 and observe two transfers.",hint:"Choose a release angle of at least 45\xB0. Without damping the rise matches the release."},slow:{title:"A slow cradle",description:"Produce at least two transfers with a small-angle period of 3 s or longer.",hint:"Try a longer string or the Moon\u2019s gravity."},damping:{title:"Let the motion fade",description:"Observe two or more transfers and leave less than 20% of the initial energy.",hint:"Turn on swing damping and run the experiment to the end."}}}},n={sim:a};export{n as default,a as sim};
